document.addEventListener("DOMContentLoaded", function () {

  if (!window.gsap || !window.SplitText || !window.ScrollTrigger) {
    console.warn("[SplitMotion] GSAP, ScrollTrigger, or SplitText missing");
    return;
  }

  gsap.registerPlugin(SplitText, ScrollTrigger);
  const PRESETS = {

    /* ======================
       BASIC FADE & SLIDE
    ====================== */
    "fade-up": { opacity: 0, y: 40 },
    "fade-down": { opacity: 0, y: -40 },
    "fade-left": { opacity: 0, x: 40 },
    "fade-right": { opacity: 0, x: -40 },

    "slide-up": { y: 80 },
    "slide-down": { y: -80 },
    "slide-left": { x: 80 },
    "slide-right": { x: -80 },

    "micro-slide": { y: 10, duration: 0.3 },
    "quick-in": { duration: 0.25 },


    /* ======================
       SCALE / ZOOM
    ====================== */
    "zoom-in": { opacity: 0, scale: 0.6 },
    "zoom-out": { opacity: 0, scale: 1.4 },
    "scale-pop": { scale: 0.5 },
    "scale-soft": { scale: 0.85 },

    "pop": {
      opacity: 0,
      scale: 0.3,
      duration: 0.6,
      ease: "back.out(2)"
    },

    "soft-zoom": {
      opacity: 0,
      scale: 0.85,
      duration: 0.9,
      ease: "power2.out"
    },


    /* ======================
       ROTATE / FLIP
    ====================== */
    "rotate-in": { opacity: 0, rotate: 12 },
    "rotate-out": { opacity: 0, rotate: -12 },
    "spin-in": { opacity: 0, rotate: 180 },

    "flip-x": { opacity: 0, rotateX: 90 },
    "flip-y": { opacity: 0, rotateY: 90 },

    "flip-up": {
      opacity: 0,
      rotateX: -90,
      y: 40,
      duration: 0.8,
      ease: "power3.out"
    },

    "flip-left": {
      opacity: 0,
      rotateY: -90,
      x: -40,
      duration: 0.8,
      ease: "power3.out"
    },

    "flip-right": {
      opacity: 0,
      rotateY: 90,
      x: 40,
      duration: 0.8,
      ease: "power3.out"
    },

    "rise-rotate": {
      opacity: 0,
      y: 60,
      rotate: 8,
      duration: 0.9,
      ease: "power3.out"
    },


    /* ======================
       BLUR / CINEMATIC
    ====================== */
    "blur-in": { opacity: 0, blur: 14 },
    "blur-soft": { opacity: 0, blur: 6 },

    "cinematic": {
      opacity: 0,
      y: 80,
      blur: 16,
      duration: 1.2,
      ease: "power3.out"
    },

    "cinematic-strong": {
      opacity: 0,
      y: 140,
      blur: 20,
      scale: 0.9,
      duration: 1.4,
      ease: "power4.out"
    },

    "hero": {
      opacity: 0,
      y: 100,
      blur: 12,
      scale: 0.95,
      duration: 1.6,
      ease: "power4.out"
    },

    "hero-reveal": {
      opacity: 0,
      y: 100,
      scale: 0.9,
      blur: 20,
      duration: 1.5,
      ease: "expo.out"
    },

    "dramatic": {
      opacity: 0,
      y: 180,
      blur: 24,
      scale: 0.8,
      duration: 1.8,
      ease: "expo.out"
    },


    /* ======================
       SMOOTH / LUXURY
    ====================== */
    "smooth": {
      opacity: 0,
      y: 24,
      duration: 0.8,
      ease: "power4.out"
    },

    "smooth-reveal": {
      opacity: 0,
      y: 20,
      duration: 1,
      ease: "power4.out"
    },

    "luxury-slow": {
      opacity: 0,
      y: 30,
      duration: 1.6,
      ease: "expo.out"
    },

    "float-in": {
      opacity: 0,
      y: 60,
      duration: 1.2,
      ease: "expo.out"
    },


    /* ======================
       ELASTIC / BOUNCE
    ====================== */
    "elastic-pop": {
      scale: 0.5,
      ease: "elastic.out(1,0.4)"
    },

    "elastic-up": {
      opacity: 0,
      y: 100,
      duration: 1,
      ease: "elastic.out(1,0.5)"
    },

    "bounce-up": {
      opacity: 0,
      y: 120,
      duration: 0.9,
      ease: "back.out(1.7)"
    },


    /* ======================
       CHARACTER FX
    ====================== */
    "char-wave": { y: 30 },
    "char-wave-soft": { y: 15 },
    "char-jump": { y: 80, ease: "bounce.out" },
    "char-flicker": { opacity: 0 },
    "char-spiral": { rotate: 45, scale: 0.5 },


    /* ======================
       3D / DEPTH
    ====================== */
    "push-z": { z: 120, scale: 0.9 },
    "pull-z": { z: -120, scale: 1.1 },
    "tilt-in": { rotateX: 45, y: 40 },


    /* ======================
       SPECIAL FX
    ====================== */
    "glitch-in": {
      opacity: 0,
      x: -20,
      blur: 8,
      duration: 0.4,
      ease: "steps(2)"
    },


    /* ======================
       PARAGRAPH PRESETS
       (RECOMMENDED: mode="lines")
    ====================== */
    "paragraph": {
      opacity: 0,
      y: 24,
      duration: 0.8,
      ease: "power2.out",
      stagger: 0.04
    },

    "paragraph-soft": {
      opacity: 0,
      y: 16,
      duration: 1,
      ease: "power1.out",
      stagger: 0.03
    },

    "paragraph-blur": {
      opacity: 0,
      y: 20,
      blur: 6,
      duration: 1,
      ease: "power2.out",
      stagger: 0.04
    },

    "paragraph-smooth": {
      opacity: 0,
      y: 30,
      duration: 1.2,
      ease: "expo.out",
      stagger: 0.05
    },

    "paragraph-fade": {
      opacity: 0,
      duration: 0.8,
      ease: "power1.out",
      stagger: 0.03
    },

    "paragraph-luxury": {
      opacity: 0,
      y: 40,
      blur: 8,
      duration: 1.4,
      ease: "expo.out",
      stagger: 0.06
    },

    "paragraph-slide-left": {
      opacity: 0,
      x: -40,
      duration: 0.9,
      ease: "power2.out",
      stagger: 0.04
    },

    "paragraph-slide-right": {
      opacity: 0,
      x: 40,
      duration: 0.9,
      ease: "power2.out",
      stagger: 0.04
    }

  };

  function init(root = document) {

    const elements = root.querySelectorAll("[data-split]");

    elements.forEach((el) => {

      if (el.__splitAnimated) return;
      el.__splitAnimated = true;

      const mode = el.dataset.mode ?? "words";
      const split = new SplitText(el, { type: mode });

      const targets =
        mode === "chars"
          ? split.chars
          : mode === "lines"
            ? split.lines
            : split.words;

      let presetConfig = {};

      Object.keys(PRESETS).forEach((preset) => {
        if (el.hasAttribute(`data-${preset}`)) {
          presetConfig = PRESETS[preset];
        }
      });

      const config = {
        opacity: Number(el.dataset.opacity ?? presetConfig.opacity ?? 0),
        x: Number(el.dataset.x ?? presetConfig.x ?? 0),
        y: Number(el.dataset.y ?? presetConfig.y ?? 40),
        z: Number(el.dataset.z ?? presetConfig.z ?? 0),
        scale: Number(el.dataset.scale ?? presetConfig.scale ?? 1),
        rotate: Number(el.dataset.rotate ?? presetConfig.rotate ?? 0),
        rotateX: Number(el.dataset.rotateX ?? presetConfig.rotateX ?? 0),
        rotateY: Number(el.dataset.rotateY ?? presetConfig.rotateY ?? 0),
        duration: Number(el.dataset.duration ?? presetConfig.duration ?? 0.4),
        delay: Number(el.dataset.delay ?? 0),
        stagger: Number(el.dataset.stagger ?? 0.08),
        ease: el.dataset.ease ?? presetConfig.ease ?? "power2.out",
        filter: `blur(${el.dataset.blur ?? presetConfig.blur ?? 0}px)`
      };

      if (el.dataset.scroll !== "false") {
        config.scrollTrigger = {
          trigger: el,
          start: el.dataset.start ?? "top 80%",
          end: el.dataset.end ?? "bottom top"
        };
      }

      gsap.from(targets, config);

    });
  }

  // Auto init
  init();

  // Optional: expose global API
  window.SplitMotion = { init };

});
